mapper.select:
SELECT /*SQL-ID : isry.couns.constt.bbserr.mapper.BbsErrListMapper : 전산오류(조회)*/ EE.BBSCTT_CN AS BBSCTT_CN , EE.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , CASE WHEN EE.NUM = '2' THEN 'RE: ' || EE.BBSCTT_TTL_NM ELSE EE.BBSCTT_TTL_NM END AS BBSCTT_TTL_NM , EE.DTPRSN_ERR_DCLR_ERR_SE_CD AS DTPRSN_ERR_DCLR_ERR_SE_CD , EE.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD AS DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD , TO_CHAR(EE.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT /*최초등록일*/ , EE.FRST_RGTR_ID || '(' || EE.WRTR_NM_ENCPT || ')' AS FRST_RGTR_ID /*등록아이디*/ , EE.RDCNT_NOCS AS RDCNT_NOCS /*조회수*/ , C##RG.DEC_B64(EE.WRTR_NM_ENCPT) AS WRTR_NM_ENCPT /*작성자명*/ , EE.ATFINO AS ATFINO /*첨부*/ , EE.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , NUM , COUNT(*) OVER() AS TOTAL_COUNT FROM ( SELECT AA.BBSCTT_CN AS BBSCTT_CN /*내용*/ , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO /*게시글번호*/ , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM /*게시글제목*/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_ERR_SE_CD' AND A1.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_ERR_SE_CD ) AS DTPRSN_ERR_DCLR_ERR_SE_CD /*분류유형*/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD ) AS DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD /*진행상태*/ , AA.FRST_REG_DT AS FRST_REG_DT /*등록일*/ , AA.FRST_RGTR_ID || '(' || AA.WRTR_NM_ENCPT || ')' AS FRST_RGTR_ID /*등록아이디*/ , AA.RDCNT_NOCS AS RDCNT_NOCS /*조회수*/ , AA.WRTR_NM_ENCPT AS WRTR_NM_ENCPT /*작성자명*/ , AA.ATFINO AS ATFINO /*첨부*/ , 0 AS RETE_ESNTAL_NO , '1' AS NUM FROM AYE100 AS AA WHERE 1=1 AND AA.BBSCTT_TYPE_SE_CD = '30' AND AA.DEL_YN = 'N' /* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01'
/* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02'
/* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03'
/* 분류 : 채팅에러 ==> 기본값 */ AND DTPRSN_ERR_DCLR_ERR_SE_CD = '01' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 분류 : 그외 오류 */ AND DTPRSN_ERR_DCLR_ERR_SE_CD = '02' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 검색어 조건 : 작성자 일 때 */ /* 검색어로 조회 */ AND AA.WRTR_NM_ENCPT LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 제목 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_TTL_NM LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 번호 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_ESNTAL_NO LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 내용 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_CN LIKE '%' || #{KEYWORD} || '%'
AND AA.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND AA.FRST_REG_DT < TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
UNION ALL SELECT BB.RETE_CN AS BBSCTT_CN /*내용*/ , BB.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO /*게시글번호*/ , BB.RETE_TTL_NM AS BBSCTT_TTL_NM /*게시글제목*/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_ERR_SE_CD' AND A1.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_ERR_SE_CD ) AS DTPRSN_ERR_DCLR_ERR_SE_CD /*분류유형*/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD ) AS DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD /*진행상태*/ , BB.FRST_REG_DT AS FRST_REG_DT /*등록일*/ , BB.FRST_RGTR_ID || '(' || AA.WRTR_NM_ENCPT || ')' AS FRST_RGTR_ID /*등록아이디*/ , BB.RDCNT_NOCS AS RDCNT_NOCS /*조회수*/ , BB.WRTR_NM_ENCPT AS WRTR_NM_ENCPT /*작성자명*/ , BB.ATFINO AS ATFINO /*첨부*/ , BB.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , '2' AS NUM FROM AYE120 AS BB , AYE100 AS AA WHERE 1=1 AND BB.BBSCTT_TYPE_SE_CD = '30' AND BB.BBSCTT_TYPE_SE_CD = AA.BBSCTT_TYPE_SE_CD AND BB.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO AND BB.BBSCTT_TYPE_SE_CD IS NOT NULL AND BB.DEL_YN = 'N' AND AA.DEL_YN = 'N' /* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '01'
/* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '02'
/* 상태 : 접수 ==> 기본값*/ AND DTPRSN_ERR_DCLR_PRGRS_STTS_SE_CD = '03'
/* 분류 : 채팅에러 ==> 기본값 */ AND DTPRSN_ERR_DCLR_ERR_SE_CD = '01' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 분류 : 그외 오류 */ AND DTPRSN_ERR_DCLR_ERR_SE_CD = '02' /* 전산오류신고오류구분코드(분류 ==> 채팅에러(01), 그외 오류(02)) */
/* 검색어 조건 : 작성자 일 때 */ /* 검색어로 조회 */ AND AA.WRTR_NM_ENCPT LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 제목 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_TTL_NM LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 번호 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_ESNTAL_NO LIKE '%' || #{KEYWORD} || '%'
/* 검색어 조건 : 내용 일 때 */ /* 검색어로 조회 */ AND AA.BBSCTT_CN LIKE '%' || #{KEYWORD} || '%'
AND AA.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS') AND AA.FRST_REG_DT < TO_DATE(#{END_DATE} || '000000', 'YYYYMMDDHH24MISS')+1
) AS EE ORDER BY EE.BBSCTT_ESNTAL_NO DESC , EE.NUM OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.update:
UPDATE AYE120 SET /*SQL-ID : isry.couns.constt.bbserr.mapper.BbsErrListMapper : 전산오류(답글수정)*/ RETE_CN = #{RETE_CN}
, RETE_TTL_NM = #{RETE_TTL_NM} /*게시글제목*/
, PSWD_ENCPT = #{PSWD_ENCPT} /*글비번*/
, ATFINO = #{ATFINO} /*파일*/
, LAST_MDFCN_DT = SYSDATE , LAST_MDFR_ID = #{LAST_MDFR_ID} WHERE 1=1 AND BBSCTT_TYPE_SE_CD = '30' AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin} AND RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE AYE120 SET /*SQL-ID : isry.couns.constt.bbserr.mapper.BbsErrListMapper :  전산오류(답글삭제)*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '30'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}
